<?php
namespace Xdecaro\Component\Decarofinance\Administrator\View\Dashboard;
defined('_JEXEC') or die;
use Joomla\CMS\Factory; use Joomla\CMS\Language\Text; use Joomla\CMS\MVC\View\HtmlView as BaseHtmlView; use Joomla\CMS\Toolbar\ToolbarHelper; use Xdecaro\Component\Decarofinance\Administrator\Service\CoreIntegrationService; use Xdecaro\Component\Decarofinance\Administrator\Service\FinanceQueryService;
final class HtmlView extends BaseHtmlView { public bool $coreUiActive=false; public array $summary=[]; public function display($tpl=null):void { $app=Factory::getApplication(); if(!$app->getIdentity()->authorise('core.manage','com_decarofinance')) throw new \RuntimeException(Text::_('JERROR_ALERTNOAUTHOR'),403); ToolbarHelper::title(Text::_('COM_DECAROFINANCE'),'credit'); $wa=$app->getDocument()->getWebAssetManager(); $wa->getRegistry()->addExtensionRegistryFile('com_decarofinance'); try{$this->coreUiActive=Factory::getContainer()->get(CoreIntegrationService::class)->enableUi($wa);}catch(\Throwable){$this->coreUiActive=false;} $wa->useStyle('com_decarofinance.admin'); $this->summary=Factory::getContainer()->get(FinanceQueryService::class)->getSummary(); parent::display($tpl); } }
